using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class CriticalInventory {
 public static object Run(){var all=SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var items=new[]{"S1_VitalMonitor_18","Clinical_PPE_Station","S1_ServiceBackboard_Support","Observation_Console_A"}.Select(n=>{var t=all.Single(t=>t.name==n);return new{n,pos=t.position.ToString("F3"),rotation=t.eulerAngles.ToString("F3"),children=t.GetComponentsInChildren<MeshFilter>(true).Select(m=>new{m.name,mesh=AssetDatabase.GetAssetPath(m.sharedMesh),prefab=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(m.gameObject),vertices=m.sharedMesh.vertexCount,bounds=m.sharedMesh.bounds.ToString(),localPos=m.transform.localPosition.ToString(),localRot=m.transform.localEulerAngles.ToString(),scale=m.transform.lossyScale.ToString(),mats=m.GetComponent<Renderer>().sharedMaterials.Select(a=>new{a.name,path=AssetDatabase.GetAssetPath(a)})})};}).ToArray();string o=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/C01_Perimeter/critical_inventory.json"));File.WriteAllText(o,JsonConvert.SerializeObject(items,Formatting.Indented));return items;}
}
